#include <bits/stdc++.h>
using namespace std;

class Base62Encoder {
public:
    static const string ALPHABET;
    static const int BASE = 62;
    static const int CODE_LENGTH = 7;

    static string encode(long long id) {
        string result;
        long long value = id;
        while (value > 0) {
            result += ALPHABET[value % BASE];
            value /= BASE;
        }
        while ((int)result.size() < CODE_LENGTH) {
            result += ALPHABET[0];
        }
        reverse(result.begin(), result.end());
        return result;
    }

    static long long decode(const string& shortCode) {
        long long value = 0;
        for (char ch : shortCode) {
            value = value * BASE + ALPHABET.find(ch);
        }
        return value;
    }
};

const string Base62Encoder::ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

int main() {
    long long id = 125;
    string code = Base62Encoder::encode(id);
    long long decoded = Base62Encoder::decode(code);
    cout << "id=" << id << " -> code=" << code << " -> decoded=" << decoded << endl;
    return 0;
}

