public class IdGeneratorService {

    private static final int BLOCK_SIZE = 1000;

    private final IdRangeRepository idRangeRepository;
    private final AtomicLong currentId = new AtomicLong(0);
    private final AtomicLong maxIdInBlock = new AtomicLong(0);
    private final Object lock = new Object();

    public IdGeneratorService(IdRangeRepository idRangeRepository) {
        this.idRangeRepository = idRangeRepository;
    }

    public long nextId() {
        long id = currentId.incrementAndGet();
        if (id > maxIdInBlock.get()) {
            synchronized (lock) {
                // Double-checked: another thread may have already refilled the block.
                if (id > maxIdInBlock.get()) {
                    allocateNewBlock();
                    id = currentId.incrementAndGet();
                }
            }
        }
        return id;
    }

    private void allocateNewBlock() {
        // Atomically reserves the next BLOCK_SIZE ids in a single database
        // round trip, so no other instance can ever claim the same range.
        long blockStart = idRangeRepository.reserveNextBlock(BLOCK_SIZE);
        currentId.set(blockStart);
        maxIdInBlock.set(blockStart + BLOCK_SIZE);
    }
}

