#include <bits/stdc++.h>
using namespace std;

class IdRangeRepository {
public:
    virtual long long reserveNextBlock(int blockSize) = 0;
    virtual ~IdRangeRepository() = default;
};

// a trivial in-memory stand-in, a real implementation would atomically
// increment a counter row in the database
class InMemoryIdRangeRepository : public IdRangeRepository {
    long long nextBlockStart = 0;
    mutex mtx;
public:
    long long reserveNextBlock(int blockSize) override {
        lock_guard<mutex> guard(mtx);
        long long start = nextBlockStart;
        nextBlockStart += blockSize;
        return start;
    }
};

class IdGeneratorService {
    static const int BLOCK_SIZE = 1000;
    IdRangeRepository& idRangeRepository;
    long long currentId = 0;
    long long maxIdInBlock = 0;
    mutex lockMtx;

public:
    IdGeneratorService(IdRangeRepository& idRangeRepository) : idRangeRepository(idRangeRepository) {}

    long long nextId() {
        lock_guard<mutex> guard(lockMtx);
        currentId++;
        if (currentId > maxIdInBlock) {
            allocateNewBlock();
            currentId++;
        }
        return currentId;
    }

private:
    void allocateNewBlock() {
        // Atomically reserves the next BLOCK_SIZE ids in a single database
        // round trip, so no other instance can ever claim the same range.
        long long blockStart = idRangeRepository.reserveNextBlock(BLOCK_SIZE);
        currentId = blockStart;
        maxIdInBlock = blockStart + BLOCK_SIZE;
    }
};

int main() {
    InMemoryIdRangeRepository repo;
    IdGeneratorService idGeneratorService(repo);
    for (int i = 0; i < 5; i++) {
        cout << "Generated id: " << idGeneratorService.nextId() << endl;
    }
    return 0;
}

