using Clock = chrono::system_clock;

class UrlMapping {
public:
    string shortCode;
    string longUrl;
    string userId;                        // empty means anonymous links allowed
    Clock::time_point createdAt;
    optional<Clock::time_point> expiresAt; // nullopt means links can live forever
    bool isActive = false;

    bool isExpired() const {
        return expiresAt.has_value() && Clock::now() > expiresAt.value();
    }

    bool isResolvable() const {
        return isActive && !isExpired();
    }
};

