    mapping.shortCode = "a1B2c3D";
    mapping.longUrl = "https://example.com/a/very/long/path";
    mapping.createdAt = Clock::now();
    mapping.isActive = true;

    cout << "Is resolvable: " << (mapping.isResolvable() ? "true" : "false") << endl;
    return 0;
}

