@Service
public class ShorteningService {

    private final IdGeneratorService idGeneratorService;
    private final UrlRepository urlRepository;
    private final UrlValidator urlValidator;

    public ShorteningService(IdGeneratorService idGeneratorService,
                              UrlRepository urlRepository,
                              UrlValidator urlValidator) {
        this.idGeneratorService = idGeneratorService;
        this.urlRepository = urlRepository;
        this.urlValidator = urlValidator;
    }

    public UrlMapping createShortUrl(String longUrl, String customAlias,
                                      Instant expiresAt, String userId) {
        urlValidator.validate(longUrl);  // length, format, blacklist check from §21

        String shortCode;
        if (customAlias != null) {
            if (urlRepository.existsByShortCode(customAlias)) {
                throw new AliasUnavailableException(customAlias);
            }
            shortCode = customAlias;
        } else {
            shortCode = Base62Encoder.encode(idGeneratorService.nextId());
        }

        UrlMapping mapping = new UrlMapping();
        mapping.setShortCode(shortCode);
        mapping.setLongUrl(longUrl);
        mapping.setUserId(userId);
        mapping.setCreatedAt(Instant.now());
        mapping.setExpiresAt(expiresAt);
        mapping.setActive(true);

        // Retry once on the rare chance an auto-generated code collides.
        try {
            urlRepository.save(mapping);
        } catch (DuplicateKeyException e) {
            if (customAlias != null) throw new AliasUnavailableException(customAlias);
            mapping.setShortCode(Base62Encoder.encode(idGeneratorService.nextId()));
            urlRepository.save(mapping);
        }
        return mapping;
    }
}

