class Base62Encoder {
public:
    static const string ALPHABET;
    static const int BASE = 62;
    static const int CODE_LENGTH = 7;

    static string encode(long long id) {
        string result;
        long long value = id;
        while (value > 0) {
            result += ALPHABET[value % BASE];
            value /= BASE;
        }
        while ((int)result.size() < CODE_LENGTH) {
            result += ALPHABET[0];
        }
        reverse(result.begin(), result.end());
        return result;
    }
};
